const crypto = require("crypto");
let publicKey = `
-----BEGIN PUBLIC KEY-----
MIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQCizC39semRSp/09DVfFO8U9pVJ
z+MvRuKf/YWAeobmA8C4wgL5hmYihc+sBVnq4njDv2krG+idEPK3iFbNokox1Sx7
h53LiuI8D1ouIAqwMuzGrJOuUyMVtQvoReOzBHTA6gXgVIzqu4L70fcgp+fSEUuO
wht0eX3HbyiAyuxPcQIDAQAB
-----END PUBLIC KEY-----
`;

function 获取内容(内容) {
    if (内容) {
        if (typeof 内容 === 'string' || 内容 instanceof Buffer) {
            return 内容;
        } else if (内容 instanceof String) {
            return 内容.toString();
        } else {
            return JSON.stringify(内容);
        }
    } else {
        return 内容;
    }
}

function 生成签名(msg, 密钥) {
    const sign = crypto.createSign('sha256');
    sign.update('主题:');
    sign.update(msg.主题);
    sign.update('接收名字空间:');
    sign.update(msg.接收名字空间);
    sign.update('时间:');
    sign.update(msg.时间);
    sign.update('内容:');
    sign.update(获取内容(msg.内容));
    sign.end();
    const signature = sign.sign(密钥);
    let v = signature.toString('base64');
    return v;
}

function 验证签名(msg) {
    if (!msg.签名) {
        return false;
    }
    const verify = crypto.createVerify('sha256');
    verify.update('主题:');
    verify.update(msg.主题);
    verify.update('接收名字空间:');
    verify.update(msg.接收名字空间);
    verify.update('时间:');
    verify.update(msg.时间 || '');
    verify.update('内容:');
    verify.update(获取内容(msg.内容));
    verify.end();
    let b = Buffer.from(msg.签名, 'base64');
    return verify.verify(publicKey, b);
}


module.exports = {
    获取内容,
    生成签名,
    验证签名
};

